<?php
/* SaaS plans (limits, modules, prices) and platform settings (approval, trial, grace period, payment instructions, reminder key). */
require __DIR__ . '/inc/boot.php'; require_once __DIR__ . '/../biz/inc/saas.php';
$admin = require_login(); $pdo = db(); require_perm('bizplans.view'); $self = 'biz-plans.php';
ob_start();
try {
  biz_ensure_plans($pdo);
  if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    deny_unless('bizplans.edit', $self); $do = (string) ($_POST['do'] ?? '');
    if ($do === 'plan') {
        $id = (int) ($_POST['id'] ?? 0); $n = fn($k, $max = 99999999) => max(0, min($max, (int) ($_POST[$k] ?? 0))); $mods = array_values(array_intersect(array_keys(BIZ_MODULES), (array) ($_POST['modules'] ?? [])));
        $name = mb_substr(trim((string) ($_POST['name'] ?? '')), 0, 80); $code = strtolower(preg_replace('/[^a-z0-9_-]/i', '', (string) ($_POST['code'] ?? '')));
        $pu = number_format(max(0, (float) str_replace(',', '', (string) ($_POST['price_ugx'] ?? 0))), 2, '.', ''); $pd = number_format(max(0, (float) str_replace(',', '', (string) ($_POST['price_usd'] ?? 0))), 2, '.', '');
        if ($name === '' || ($code === '' && !$id)) flash('Name and code are required.', 'bad');
        else {
            $vals = [$name, $pu, $pd, max(1, $n('duration_days', 3650)), $n('max_users'), $n('max_branches'), $n('max_docs_month'), $n('storage_mb'), implode(',', $mods), mb_substr(trim((string) ($_POST['features'] ?? '')), 0, 1000), empty($_POST['is_public']) ? 0 : 1, empty($_POST['is_active']) ? 0 : 1, $n('sort_order', 999)];
            if ($id) $pdo->prepare('UPDATE biz_plans SET name=?, price_ugx=?, price_usd=?, duration_days=?, max_users=?, max_branches=?, max_docs_month=?, storage_mb=?, modules=?, features=?, is_public=?, is_active=?, sort_order=? WHERE id=?')->execute([...$vals, $id]);
            else { try { $pdo->prepare('INSERT INTO biz_plans (name, price_ugx, price_usd, duration_days, max_users, max_branches, max_docs_month, storage_mb, modules, features, is_public, is_active, sort_order, code) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([...$vals, $code]); } catch (Throwable $e) { flash('That plan code already exists.', 'bad'); redirect($self); } }
            log_activity((int) $admin['id'], 'biz_plan_save', $name); flash('Plan saved.');
        }
    } elseif ($do === 'settings') {
        foreach (['biz_trial_days' => 3, 'biz_grace_days' => 3, 'biz_momo_number' => 30, 'biz_airtel_number' => 30, 'biz_bank_details' => 500, 'biz_cron_key' => 64] as $k => $m) save_doc_setting($pdo, $k, mb_substr(trim((string) ($_POST[$k] ?? '')), 0, $m));
        save_doc_setting($pdo, 'biz_signup_approval', empty($_POST['biz_signup_approval']) ? '0' : '1'); log_activity((int) $admin['id'], 'biz_settings', ''); flash('Platform settings saved.');
    }
    redirect($self);
  }
  $plans = $pdo->query('SELECT * FROM biz_plans ORDER BY sort_order, id')->fetchAll(); $can = can('bizplans.edit'); $edit = null; foreach ($plans as $p) if (isset($_GET['edit']) && (int) $_GET['edit'] === (int) $p['id']) $edit = $p;
  $S = fn($k, $d = '') => doc_setting($k, $d);
  $sec = fn($n) => (getenv($n) !== false && getenv($n) !== '') || (is_file(storage_dir() . '/payment-secrets.php') && !empty((include storage_dir() . '/payment-secrets.php')[$n]));
  page_head('SaaS plans and settings', $admin, 'bizacc:plans');
  echo '<div class="card"><div class="card-header"><h3 class="card-title">Plans</h3></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Plan</th><th>Price</th><th>Limits</th><th>Modules</th><th></th></tr></thead><tbody>';
  foreach ($plans as $p) echo '<tr><td><b>' . h($p['name']) . '</b><div class="small text-muted">' . h($p['code']) . ($p['is_active'] ? '' : ' · inactive') . ($p['is_public'] ? '' : ' · hidden') . '</div></td><td class="small">' . ((float) $p['price_ugx'] > 0 ? h(number_format((float) $p['price_ugx'])) . ' UGX' : 'UGX not set') . '<br>' . ((float) $p['price_usd'] > 0 ? h(number_format((float) $p['price_usd'], 2)) . ' USD' : 'USD not set') . '<br>' . (int) $p['duration_days'] . ' days</td><td class="small">' . ((int) $p['max_users'] ?: '∞') . ' users<br>' . ((int) $p['max_branches'] ?: '∞') . ' branches<br>' . ((int) $p['max_docs_month'] ?: '∞') . ' docs/month<br>' . ((int) $p['storage_mb'] ?: '∞') . ' MB</td><td class="small">' . h($p['modules']) . '</td><td>' . ($can ? '<a class="btn btn-sm btn-outline-primary" href="?edit=' . (int) $p['id'] . '">Edit</a>' : '') . '</td></tr>';
  echo '</tbody></table></div></div><p class="text-muted small">0 means unlimited. Prices start at 0 on purpose: set your own. A plan with no price for a currency cannot be paid for online in that currency.</p>';
  if ($can) {
    $v = $edit ?: ['id' => 0, 'code' => '', 'name' => '', 'price_ugx' => '', 'price_usd' => '', 'duration_days' => 30, 'max_users' => 0, 'max_branches' => 0, 'max_docs_month' => 0, 'storage_mb' => 0, 'modules' => 'docs,customers,items', 'features' => '', 'is_public' => 1, 'is_active' => 1, 'sort_order' => count($plans) + 1]; $mods = explode(',', (string) $v['modules']);
    echo '<div class="card"><div class="card-header"><h3 class="card-title">' . ($edit ? 'Edit plan' : 'Add plan') . '</h3></div><div class="card-body"><form method="post" class="row g-3">' . csrf_field() . '<input type="hidden" name="do" value="plan"><input type="hidden" name="id" value="' . (int) $v['id'] . '">'
       . '<div class="col-md-3"><label class="form-label">Name</label><input class="form-control" name="name" required value="' . h($v['name']) . '"></div><div class="col-md-2"><label class="form-label">Code</label><input class="form-control" name="code" value="' . h($v['code']) . '"' . ($edit ? ' disabled' : ' required') . '></div>'
       . '<div class="col-md-2"><label class="form-label">Price UGX</label><input class="form-control" name="price_ugx" value="' . h((string) $v['price_ugx']) . '"></div><div class="col-md-2"><label class="form-label">Price USD</label><input class="form-control" name="price_usd" value="' . h((string) $v['price_usd']) . '"></div><div class="col-md-3"><label class="form-label">Days per payment</label><input class="form-control" type="number" name="duration_days" value="' . (int) $v['duration_days'] . '"></div>';
    foreach (['max_users' => 'Users', 'max_branches' => 'Branches', 'max_docs_month' => 'Documents/month', 'storage_mb' => 'Storage MB', 'sort_order' => 'Order'] as $k => $l) echo '<div class="col-6 col-md-2"><label class="form-label">' . $l . '</label><input class="form-control" type="number" min="0" name="' . $k . '" value="' . (int) $v[$k] . '"></div>';
    echo '<div class="col-12"><label class="form-label">Modules</label><div>'; foreach (BIZ_MODULES as $k => $l) echo '<label class="me-3"><input type="checkbox" name="modules[]" value="' . $k . '"' . (in_array($k, $mods, true) ? ' checked' : '') . '> ' . h($l) . '</label>';
    echo '</div></div><div class="col-12"><label class="form-label">Feature notes shown to businesses</label><input class="form-control" name="features" maxlength="1000" value="' . h((string) $v['features']) . '"></div><div class="col-12"><label class="me-3"><input type="checkbox" name="is_public" value="1"' . ($v['is_public'] ? ' checked' : '') . '> Show on sign-up and billing</label><label><input type="checkbox" name="is_active" value="1"' . ($v['is_active'] ? ' checked' : '') . '> Active</label></div><div class="col-12"><button class="btn btn-primary">Save plan</button> ' . ($edit ? '<a class="btn btn-outline-secondary" href="' . $self . '">Cancel</a>' : '') . '</div></form></div></div>';
    echo '<div class="card"><div class="card-header"><h3 class="card-title">Platform settings</h3></div><div class="card-body"><form method="post" class="row g-3">' . csrf_field() . '<input type="hidden" name="do" value="settings">'
       . '<div class="col-md-3"><label class="form-label">Free trial days</label><input class="form-control" type="number" name="biz_trial_days" value="' . h($S('biz_trial_days', '14')) . '"></div><div class="col-md-3"><label class="form-label">Grace days after expiry</label><input class="form-control" type="number" name="biz_grace_days" value="' . h($S('biz_grace_days', '7')) . '"></div>'
       . '<div class="col-md-6 d-flex align-items-end"><label><input type="checkbox" name="biz_signup_approval" value="1"' . ($S('biz_signup_approval', '0') === '1' ? ' checked' : '') . '> New registrations need my approval first</label></div>'
       . '<div class="col-md-4"><label class="form-label">MTN Mobile Money number (shown to payers)</label><input class="form-control" name="biz_momo_number" value="' . h($S('biz_momo_number')) . '"></div><div class="col-md-4"><label class="form-label">Airtel Money number</label><input class="form-control" name="biz_airtel_number" value="' . h($S('biz_airtel_number')) . '"></div><div class="col-md-4"><label class="form-label">Reminder cron key</label><input class="form-control" name="biz_cron_key" value="' . h($S('biz_cron_key')) . '" placeholder="random text"></div>'
       . '<div class="col-12"><label class="form-label">Bank transfer details</label><textarea class="form-control" name="biz_bank_details" rows="2">' . h($S('biz_bank_details')) . '</textarea></div><div class="col-12"><button class="btn btn-primary">Save settings</button></div></form></div></div>';
  }
  echo '<div class="card"><div class="card-header"><h3 class="card-title">Payment credentials status</h3></div><div class="card-body small"><p>Secrets are never stored in the database. Set them as server environment variables, or in <code>storage/payment-secrets.php</code> (returns an array of name => value), outside the public web root.</p><ul class="mb-2">';
  foreach (['STRIPE_SECRET_KEY' => 'Stripe: secret API key (cards, Visa, Mastercard)', 'STRIPE_WEBHOOK_SECRET' => 'Stripe: webhook signing secret (endpoint /biz/webhook-stripe.php)', 'MTN_MOMO_SUBSCRIPTION_KEY' => 'MTN MoMo API: subscription key', 'MTN_MOMO_API_USER' => 'MTN MoMo API: API user', 'MTN_MOMO_API_KEY' => 'MTN MoMo API: API key', 'AIRTEL_CLIENT_ID' => 'Airtel Money API: client ID', 'AIRTEL_CLIENT_SECRET' => 'Airtel Money API: client secret'] as $n => $l) echo '<li>' . ($sec($n) ? '<span class="text-success">set</span>' : '<span class="text-danger">missing</span>') . ' <code>' . h($n) . '</code> ' . h($l) . '</li>';
  echo '</ul><p class="mb-0">Until MTN and Airtel API credentials are connected, those payments are confirmed by you under Subscription payments, then the plan activates automatically.</p></div></div>';
} catch (Throwable $e) { ob_clean(); page_head('SaaS plans and settings', $admin, 'bizacc:plans'); mod_setup_notice($e); }
page_foot(); ob_end_flush();
